import base64, os

def save(path, b64):
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    with open(path, 'wb') as f:
        f.write(base64.b64decode(b64))
    print('Wrote', path)

save('src/components/explorer/LayerControl.tsx', ''.replace('fSkgPT4ge30pU3QK', 'fSkgPT4gewogICAgICAgIH0pfQo='))
